package com.discordlootstreamer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("discordlootstreamer")
public interface DiscordLootStreamerConfig extends Config
{
	enum BatchTrigger
	{
		EITHER("Whichever comes first"),
		KILLS("Every N kills"),
		MINUTES("Every X minutes");

		private final String name;

		BatchTrigger(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigSection(
		name = "Triggers",
		description = "When a pending batch gets sent",
		position = 10
	)
	String triggersSection = "triggers";

	@ConfigSection(
		name = "Filters",
		description = "What loot gets included and posted",
		position = 20
	)
	String filtersSection = "filters";

	@ConfigSection(
		name = "Message",
		description = "How the Discord message looks",
		position = 30
	)
	String messageSection = "message";

	@ConfigItem(
		position = 0,
		keyName = "webhookUrl",
		name = "Discord webhook URL",
		description = "The Discord webhook to send loot batches to. Leave empty to disable.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers"
	)
	default String webhookUrl()
	{
		return "";
	}

	@ConfigItem(
		position = 11,
		keyName = "batchTrigger",
		name = "Send batch",
		description = "Which trigger sends the pending batch: kill count, elapsed time, or whichever fires first.",
		section = "triggers"
	)
	default BatchTrigger batchTrigger()
	{
		return BatchTrigger.EITHER;
	}

	@Range(min = 1)
	@ConfigItem(
		position = 12,
		keyName = "killThreshold",
		name = "N kills",
		description = "Send the pending batch once this many kills/drops have accumulated.",
		section = "triggers"
	)
	default int killThreshold()
	{
		return 10;
	}

	@Range(min = 1)
	@Units(Units.MINUTES)
	@ConfigItem(
		position = 13,
		keyName = "timeThreshold",
		name = "X minutes",
		description = "Send the pending batch once the oldest unsent loot is this many minutes old.",
		section = "triggers"
	)
	default int timeThreshold()
	{
		return 5;
	}

	@Range(min = 0)
	@ConfigItem(
		position = 14,
		keyName = "instantPostValue",
		name = "Big drop instant post",
		description = "Any single item stack worth at least this much gp posts the batch immediately, highlighted, ignoring other triggers and the min batch value. 0 disables.",
		section = "triggers"
	)
	default int instantPostValue()
	{
		return 0;
	}

	@ConfigItem(
		position = 21,
		keyName = "ignoredMonsters",
		name = "Blacklist",
		description = "Comma-separated monster/source names whose loot is ignored entirely, e.g.: Chicken, Man, Scurrius",
		section = "filters"
	)
	default String ignoredMonsters()
	{
		return "";
	}

	@Range(min = 0)
	@ConfigItem(
		position = 22,
		keyName = "minKillValue",
		name = "Min kill value",
		description = "Kills whose loot totals less than this many gp (after the min item filter) are ignored entirely — no kill quota, no loot posted. 0 includes every kill.",
		section = "filters"
	)
	default int minKillValue()
	{
		return 0;
	}

	@Range(min = 0)
	@ConfigItem(
		position = 23,
		keyName = "minItemValue",
		name = "Min item value",
		description = "Item stacks worth less than this many gp are excluded from every kill. 0 includes everything.",
		section = "filters"
	)
	default int minItemValue()
	{
		return 0;
	}

	@ConfigItem(
		position = 31,
		keyName = "includeUsername",
		name = "Include username",
		description = "Show your RSN on the Discord message.",
		section = "message"
	)
	default boolean includeUsername()
	{
		return true;
	}

	@ConfigItem(
		position = 32,
		keyName = "lootImage",
		name = "Attach loot image",
		description = "Render the batch's items like the loot tracker panel (item icons with quantities) and attach the image to the Discord message.",
		section = "message"
	)
	default boolean lootImage()
	{
		return true;
	}
}

package com.discordlootstreamer;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.plugins.loottracker.LootTrackerPlugin;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.QuantityFormatter;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@PluginDescriptor(
	name = "Discord Loot Streamer",
	description = "Streams your loot tracker drops to a Discord webhook in batches, every N kills or X minutes",
	tags = {"discord", "loot", "webhook", "drops", "tracker"}
)
@PluginDependency(LootTrackerPlugin.class)
public class DiscordLootStreamerPlugin extends Plugin
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.parse("image/png");
	private static final int EMBED_COLOR = 0xF1C40F;
	private static final int MAX_ITEM_LINES = 25;
	private static final int MAX_ICONS = 60;

	// Loot tracker panel look
	private static final Color PANEL_BG = new Color(0x25, 0x25, 0x25);
	private static final Color CELL_BG = new Color(0x39, 0x39, 0x39);
	private static final Color TEXT_WHITE = Color.WHITE;
	private static final Color TEXT_GRAY = new Color(0x9B, 0x9B, 0x9B);
	private static final Color TEXT_GOLD = new Color(255, 152, 31);
	private static final int COLS = 5;
	private static final int CELL = 40;
	private static final int GAP = 1;
	private static final int MARGIN = 5;
	private static final int HEADER_H = 20;
	private static final int SOURCE_SPACING = 6;

	@Inject
	private Client client;

	@Inject
	private DiscordLootStreamerConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private ScheduledExecutorService executor;

	private final Object batchLock = new Object();
	private final Map<String, SourceBatch> pending = new LinkedHashMap<>();
	private Instant batchStart;
	private String playerName;

	private static class BatchedItem
	{
		int id;
		String name;
		int unitPrice;
		long quantity;

		long totalValue()
		{
			return unitPrice * quantity;
		}
	}

	private static class SourceBatch
	{
		int kills;
		final Map<Integer, BatchedItem> items = new LinkedHashMap<>();
	}

	private static class SourceSnapshot
	{
		final String name;
		final int kills;
		final List<BatchedItem> items;

		SourceSnapshot(String name, int kills, List<BatchedItem> items)
		{
			this.name = name;
			this.kills = kills;
			this.items = items;
		}

		long totalValue()
		{
			return items.stream().mapToLong(BatchedItem::totalValue).sum();
		}
	}

	@Override
	protected void shutDown()
	{
		// Best-effort send of anything still pending; the request itself is async
		flush(false, null);
	}

	@Provides
	DiscordLootStreamerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DiscordLootStreamerConfig.class);
	}

	@Subscribe
	public void onLootReceived(LootReceived lootReceived)
	{
		if (config.webhookUrl().trim().isEmpty() || isBlacklisted(lootReceived.getName()))
		{
			return;
		}

		// Drop stacks under the min item value, then judge the kill by what's left
		List<ItemStack> keptStacks = new ArrayList<>();
		long killValue = 0;
		for (ItemStack stack : lootReceived.getItems())
		{
			long stackValue = (long) itemManager.getItemPrice(stack.getId()) * stack.getQuantity();
			if (config.minItemValue() > 0 && stackValue < config.minItemValue())
			{
				continue;
			}
			keptStacks.add(stack);
			killValue += stackValue;
		}

		if (keptStacks.isEmpty() || killValue < config.minKillValue())
		{
			// Nothing survived the item filter, or below the min kill value: no kill quota, no loot
			return;
		}

		boolean killTriggered;
		String bigDrop = null;
		synchronized (batchLock)
		{
			if (batchStart == null)
			{
				batchStart = Instant.now();
			}

			SourceBatch source = pending.computeIfAbsent(lootReceived.getName(), k -> new SourceBatch());
			source.kills += Math.max(1, lootReceived.getAmount());

			for (ItemStack stack : keptStacks)
			{
				BatchedItem item = source.items.get(stack.getId());
				if (item == null)
				{
					item = new BatchedItem();
					item.id = stack.getId();
					// LootReceived is posted on the client thread, so composition lookup is safe here
					item.name = itemManager.getItemComposition(stack.getId()).getName();
					item.unitPrice = itemManager.getItemPrice(stack.getId());
					source.items.put(stack.getId(), item);
				}
				item.quantity += stack.getQuantity();

				long stackValue = (long) item.unitPrice * stack.getQuantity();
				if (config.instantPostValue() > 0 && stackValue >= config.instantPostValue())
				{
					bigDrop = String.format("%s — %,d gp", item.name, stackValue);
				}
			}

			if (playerName == null && client.getLocalPlayer() != null)
			{
				playerName = client.getLocalPlayer().getName();
			}

			int totalKills = pending.values().stream().mapToInt(s -> s.kills).sum();
			killTriggered = config.batchTrigger() != DiscordLootStreamerConfig.BatchTrigger.MINUTES
				&& totalKills >= config.killThreshold();
		}

		if (bigDrop != null)
		{
			flush(true, bigDrop);
		}
		else if (killTriggered)
		{
			flush(true, null);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGIN_SCREEN)
		{
			flush(true, null);
		}
	}

	@Schedule(period = 15, unit = ChronoUnit.SECONDS)
	public void checkTimeTrigger()
	{
		if (config.batchTrigger() == DiscordLootStreamerConfig.BatchTrigger.KILLS)
		{
			return;
		}

		synchronized (batchLock)
		{
			if (batchStart == null
				|| Duration.between(batchStart, Instant.now()).compareTo(Duration.ofMinutes(config.timeThreshold())) < 0)
			{
				return;
			}
		}

		flush(true, null);
	}

	private boolean isBlacklisted(String sourceName)
	{
		if (sourceName == null)
		{
			return false;
		}

		Set<String> blacklist = Arrays.stream(config.ignoredMonsters().toLowerCase().split("[,\n]"))
			.map(String::trim)
			.filter(s -> !s.isEmpty())
			.collect(Collectors.toSet());
		return blacklist.contains(sourceName.toLowerCase().trim());
	}

	private void flush(boolean allowImage, String bigDrop)
	{
		if (HttpUrl.parse(config.webhookUrl().trim()) == null)
		{
			return;
		}

		List<SourceSnapshot> sources;
		String rsn;
		synchronized (batchLock)
		{
			if (pending.isEmpty())
			{
				return;
			}

			sources = pending.entrySet().stream()
				.map(e -> new SourceSnapshot(e.getKey(), e.getValue().kills, new ArrayList<>(e.getValue().items.values())))
				.collect(Collectors.toList());
			rsn = playerName;

			pending.clear();
			batchStart = null;
		}

		boolean hasItems = sources.stream().anyMatch(s -> !s.items.isEmpty());
		boolean attachImage = allowImage && config.lootImage() && hasItems;
		String payload = buildPayload(sources, rsn, bigDrop, attachImage);

		if (attachImage)
		{
			composeAndSend(payload, sources);
		}
		else
		{
			sendWebhook(payload, null);
		}
	}

	/**
	 * Loads the item icon sprites asynchronously, then renders the loot-tracker-style
	 * panel image and sends the webhook from the executor thread.
	 */
	private void composeAndSend(String payload, List<SourceSnapshot> sources)
	{
		int iconBudget = MAX_ICONS;
		List<List<AsyncBufferedImage>> icons = new ArrayList<>();
		List<CompletableFuture<Void>> loads = new ArrayList<>();
		for (SourceSnapshot source : sources)
		{
			source.items.sort(Comparator.comparingLong(BatchedItem::totalValue).reversed());
			List<AsyncBufferedImage> sourceIcons = new ArrayList<>();
			for (BatchedItem item : source.items)
			{
				if (iconBudget-- <= 0)
				{
					break;
				}
				int quantity = (int) Math.min(item.quantity, Integer.MAX_VALUE);
				AsyncBufferedImage icon = itemManager.getImage(item.id, quantity, item.quantity > 1);
				sourceIcons.add(icon);
				CompletableFuture<Void> load = new CompletableFuture<>();
				icon.onLoaded(() -> load.complete(null));
				loads.add(load);
			}
			icons.add(sourceIcons);
		}

		// The timeout is a fallback in case an icon never reports loaded; cached icons still render
		CompletableFuture.allOf(loads.toArray(new CompletableFuture[0]))
			.orTimeout(2, TimeUnit.SECONDS)
			.handleAsync((v, ex) ->
			{
				sendWebhook(payload, renderLootImage(sources, icons));
				return null;
			}, executor);
	}

	private static byte[] renderLootImage(List<SourceSnapshot> sources, List<List<AsyncBufferedImage>> icons)
	{
		try
		{
			int width = MARGIN * 2 + COLS * CELL + (COLS - 1) * GAP;
			int height = MARGIN;
			for (List<AsyncBufferedImage> sourceIcons : icons)
			{
				int rows = (sourceIcons.size() + COLS - 1) / COLS;
				height += HEADER_H + rows * (CELL + GAP) + SOURCE_SPACING;
			}
			height += MARGIN - SOURCE_SPACING;

			BufferedImage canvas = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
			Graphics2D g = canvas.createGraphics();
			g.setColor(PANEL_BG);
			g.fillRect(0, 0, width, height);

			Font font = FontManager.getRunescapeSmallFont();
			g.setFont(font);
			FontMetrics metrics = g.getFontMetrics();

			int y = MARGIN;
			for (int i = 0; i < sources.size(); i++)
			{
				SourceSnapshot source = sources.get(i);
				List<AsyncBufferedImage> sourceIcons = icons.get(i);

				// Header: "Name × kills" left, total value right, like the loot tracker box header
				int textY = y + (HEADER_H + metrics.getAscent() - metrics.getDescent()) / 2;
				String value = QuantityFormatter.quantityToStackSize(source.totalValue()) + " gp";
				int valueWidth = metrics.stringWidth(value);
				g.setColor(TEXT_GOLD);
				g.drawString(value, width - MARGIN - valueWidth, textY);

				String kills = " × " + source.kills;
				int nameMax = width - MARGIN * 2 - valueWidth - metrics.stringWidth(kills) - 6;
				String name = source.name;
				while (metrics.stringWidth(name) > nameMax && name.length() > 1)
				{
					name = name.substring(0, name.length() - 1);
				}
				g.setColor(TEXT_WHITE);
				g.drawString(name, MARGIN, textY);
				g.setColor(TEXT_GRAY);
				g.drawString(kills, MARGIN + metrics.stringWidth(name), textY);
				y += HEADER_H;

				// Item grid
				for (int j = 0; j < sourceIcons.size(); j++)
				{
					int cellX = MARGIN + (j % COLS) * (CELL + GAP);
					int cellY = y + (j / COLS) * (CELL + GAP);
					g.setColor(CELL_BG);
					g.fillRect(cellX, cellY, CELL, CELL);
					BufferedImage icon = sourceIcons.get(j);
					g.drawImage(icon, cellX + (CELL - icon.getWidth()) / 2, cellY + (CELL - icon.getHeight()) / 2, null);
				}
				y += ((sourceIcons.size() + COLS - 1) / COLS) * (CELL + GAP) + SOURCE_SPACING;
			}
			g.dispose();

			ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageIO.write(canvas, "png", out);
			return out.toByteArray();
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Failed to render loot image", e);
			return null;
		}
	}

	private void sendWebhook(String payloadJson, byte[] png)
	{
		HttpUrl webhook = HttpUrl.parse(config.webhookUrl().trim());
		if (webhook == null)
		{
			return;
		}

		RequestBody body;
		if (png != null)
		{
			body = new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", payloadJson)
				.addFormDataPart("file", "loot.png", RequestBody.create(PNG, png))
				.build();
		}
		else
		{
			body = RequestBody.create(JSON, payloadJson);
		}

		Request request = new Request.Builder()
			.url(webhook)
			.post(body)
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to send loot webhook", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				if (!response.isSuccessful())
				{
					log.debug("Loot webhook returned {}", response.code());
				}
				response.close();
			}
		});
	}

	private String buildPayload(List<SourceSnapshot> sources, String rsn, String bigDrop, boolean attachImage)
	{
		// Merge items across sources for the text summary
		Map<Integer, BatchedItem> merged = new LinkedHashMap<>();
		int kills = 0;
		for (SourceSnapshot source : sources)
		{
			kills += source.kills;
			for (BatchedItem item : source.items)
			{
				BatchedItem existing = merged.get(item.id);
				if (existing == null)
				{
					existing = new BatchedItem();
					existing.id = item.id;
					existing.name = item.name;
					existing.unitPrice = item.unitPrice;
					merged.put(item.id, existing);
				}
				existing.quantity += item.quantity;
			}
		}

		List<BatchedItem> items = new ArrayList<>(merged.values());
		items.sort(Comparator.comparingLong(BatchedItem::totalValue).reversed());

		long totalValue = 0;
		int shown = 0;
		StringBuilder description = new StringBuilder();

		if (bigDrop != null)
		{
			description.append("🔥 **Big drop:** ").append(bigDrop).append("\n\n");
		}

		for (BatchedItem item : items)
		{
			totalValue += item.totalValue();

			// The loot image already shows every item; only fall back to a text list without it
			if (attachImage || shown >= MAX_ITEM_LINES)
			{
				continue;
			}

			description.append(String.format("**%s** x %,d — %,d gp\n", item.name, item.quantity, item.totalValue()));
			shown++;
		}

		if (!attachImage && items.size() > MAX_ITEM_LINES)
		{
			description.append(String.format("*…and %,d more*\n", items.size() - MAX_ITEM_LINES));
		}

		JsonObject embed = new JsonObject();
		embed.addProperty("title", buildTitle(sources, kills));
		embed.addProperty("description", description.toString());
		embed.addProperty("color", EMBED_COLOR);
		embed.addProperty("timestamp", Instant.now().toString());

		JsonObject footer = new JsonObject();
		footer.addProperty("text", String.format("Total: %,d gp", totalValue));
		embed.add("footer", footer);

		if (config.includeUsername() && rsn != null)
		{
			JsonObject author = new JsonObject();
			author.addProperty("name", rsn);
			embed.add("author", author);
		}

		if (attachImage)
		{
			JsonObject image = new JsonObject();
			image.addProperty("url", "attachment://loot.png");
			embed.add("image", image);
		}

		JsonArray embeds = new JsonArray();
		embeds.add(embed);
		JsonObject payload = new JsonObject();
		payload.add("embeds", embeds);
		return gson.toJson(payload);
	}

	private static String buildTitle(List<SourceSnapshot> sources, int kills)
	{
		if (sources.size() == 1)
		{
			return String.format("💰 %s × %,d", sources.get(0).name, sources.get(0).kills);
		}

		if (sources.size() <= 3)
		{
			List<String> names = sources.stream().map(s -> s.name).collect(Collectors.toList());
			return String.format("💰 %,d kills — %s", kills, String.join(", ", names));
		}

		return String.format("💰 %,d kills — %,d sources", kills, sources.size());
	}
}

package com.discordlootstreamer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DiscordLootStreamerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DiscordLootStreamerPlugin.class);
		RuneLite.main(args);
	}
}
